from shop.errors import ValidationError

class Coupon:
    def __init__(self, code, kind, value):
        if not code:
            raise ValidationError("Coupon code cannot be empty or falsy.")
        self.code = code

        if kind not in ("percent", "fixed"):
            raise ValidationError("Coupon kind must be 'percent' or 'fixed'.")
        self.kind = kind

        if self.kind == "percent":
            if not (0 <= value <= 100):
                raise ValidationError("Percent value must be between 0 and 100.")
        elif self.kind == "fixed":
            if value < 0:
                raise ValidationError("Fixed value must be non-negative.")
        self.value = value

    def discount_for(self, subtotal_cents):
        if self.kind == "percent":
            return round(subtotal_cents * self.value / 100)
        elif self.kind == "fixed":
            return min(self.value, subtotal_cents)
